class Solution {
    public boolean hasPathSum(TreeNode root, int targetSum) {
        if (root == null) return false;
        targetSum -= root.val;
        if (root.left == null && root.right == null) return targetSum == 0;
        return hasPathSum(root.left, targetSum) || hasPathSum(root.right, targetSum);
    }
}

class Solution {
    public boolean hasPathSum(TreeNode root, int targetSum) {
        if (root == null) return false;
        Stack<Object[]> stack = new Stack<>();
        stack.push(new Object[]{root, targetSum - root.val});
        while (!stack.isEmpty()) {
            Object[] curr = stack.pop();
            TreeNode node = (TreeNode) curr[0];
            int remain = (int) curr[1];
            if (node.left == null && node.right == null && remain == 0) return true;
            if (node.right != null) stack.push(new Object[]{node.right, remain - node.right.val});
            if (node.left != null) stack.push(new Object[]{node.left, remain - node.left.val});
        }
        return false;
    }
}
